package httpapi

import (
	"context"
	"fmt"
	"log/slog"
	"net/http"
	"regexp"
	"runtime/debug"
	"time"

	"github.com/go-openapi/strfmt"
	"github.com/google/uuid"
	"github.com/labstack/echo/v5"

	"github.com/nrf24l01/actfb/internal/config"
	oapimodels "github.com/nrf24l01/actfb/internal/generated/openapi/models"
)

const (
	// TraceIDKey is the Echo context key read by generated APIError helpers.
	TraceIDKey = "trace_id"
	// HeaderRequestID is returned on every response. It is always generated by
	// the server; client-supplied values are ignored.
	HeaderRequestID = "X-Request-ID"
)

// readinessTimeout bounds a single /ready check. It is a variable so focused
// tests can use a short deadline without sleeping for the production timeout.
var readinessTimeout = 5 * time.Second

// NewRouter builds the HTTP entrypoint shared by the application and tests.
//
// ready is invoked for /ready. It must respect ctx cancellation and return a
// non-nil error when a hard dependency is unavailable. A nil ready callback is
// treated as not ready, never as success.
//
// allowedOrigins is an exact CORS allowlist. Invalid entries are ignored here
// as defense in depth; ValidateBackend rejects them at startup. No origins means
// no cross-origin support (same-origin frontend only).
func NewRouter(logger *slog.Logger, ready func(context.Context) error, allowedOrigins ...string) *echo.Echo {
	if logger == nil {
		logger = slog.Default()
	}

	e := echo.New()
	e.Logger = logger
	e.HTTPErrorHandler = errorHandler(logger)

	e.Use(
		requestIDMiddleware(),
		accessLogMiddleware(logger),
		recoveryMiddleware(logger),
	)

	if origins := validAllowedOrigins(logger, allowedOrigins); len(origins) > 0 {
		e.Use(corsMiddleware(origins))
	}

	e.GET("/health", healthHandler)
	e.GET("/ready", readinessHandler(logger, ready))

	// Keep unknown technical/API routes in the project's standard error shape.
	e.RouteNotFound("/*", func(c *echo.Context) error {
		return writeAPIError(c, http.StatusNotFound, oapimodels.ErrorCode("NOT_FOUND"), "Not found")
	})

	return e
}

func validAllowedOrigins(logger *slog.Logger, origins []string) []string {
	valid := make([]string, 0, len(origins))

	for index, origin := range origins {
		if err := config.ValidateAllowedOrigin(origin); err != nil {
			// Do not log the raw origin: it can contain userinfo or other
			// operator secrets. The index plus reason is enough to fix config.
			logger.Warn(
				"ignoring invalid CORS allowlist entry",
				"index", index,
				"reason", err.Error(),
			)
			continue
		}

		valid = append(valid, origin)
	}

	return valid
}

type statusResponse struct {
	Status string `json:"status"`
}

func healthHandler(c *echo.Context) error {
	return c.JSON(http.StatusOK, statusResponse{Status: "ok"})
}

func readinessHandler(logger *slog.Logger, ready func(context.Context) error) echo.HandlerFunc {
	return func(c *echo.Context) error {
		if ready == nil {
			logger.Warn("readiness check is not configured", "trace_id", traceID(c))
			return writeAPIError(c, http.StatusServiceUnavailable, oapimodels.ErrorCodeDEPENDENCYUNAVAILABLE, "Service unavailable")
		}

		ctx, cancel := context.WithTimeout(c.Request().Context(), readinessTimeout)
		defer cancel()

		result := make(chan error, 1)
		go func() {
			defer func() {
				if recovered := recover(); recovered != nil {
					result <- fmt.Errorf("readiness panic: %v", recovered)
				}
			}()

			result <- ready(ctx)
		}()

		select {
		case err := <-result:
			if err != nil {
				logger.Warn(
					"readiness check failed",
					"trace_id", traceID(c),
					"error", redactLogValue(err.Error()),
				)
				return writeAPIError(c, http.StatusServiceUnavailable, oapimodels.ErrorCodeDEPENDENCYUNAVAILABLE, "Service unavailable")
			}

			return c.JSON(http.StatusOK, statusResponse{Status: "ready"})

		case <-ctx.Done():
			logger.Warn(
				"readiness check timed out",
				"trace_id", traceID(c),
				"error", ctx.Err().Error(),
			)
			return writeAPIError(c, http.StatusServiceUnavailable, oapimodels.ErrorCodeDEPENDENCYUNAVAILABLE, "Service unavailable")
		}
	}
}

func requestIDMiddleware() echo.MiddlewareFunc {
	return func(next echo.HandlerFunc) echo.HandlerFunc {
		return func(c *echo.Context) error {
			id := uuid.NewString()
			c.Set(TraceIDKey, id)
			c.Response().Header().Set(HeaderRequestID, id)

			return next(c)
		}
	}
}

func accessLogMiddleware(logger *slog.Logger) echo.MiddlewareFunc {
	return func(next echo.HandlerFunc) echo.HandlerFunc {
		return func(c *echo.Context) error {
			started := time.Now()
			err := next(c)

			response, _ := echo.UnwrapResponse(c.Response())

			status := http.StatusOK
			var bytesOut int64
			if response != nil {
				status = response.Status
				bytesOut = response.Size
				if status == 0 {
					status = http.StatusOK
				}
			}
			if err != nil {
				if fromError := echo.StatusCode(err); fromError != 0 {
					status = fromError
				} else if status < http.StatusBadRequest {
					status = http.StatusInternalServerError
				}
			}

			path := c.Path()
			if path == "" {
				path = c.Request().URL.Path
			}

			// Successful probe traffic is pure noise. Only the exact matched
			// pathname is skipped and only for 2xx; failed readiness/health
			// checks stay visible, and lookalike routes are never hidden.
			if isSuccessfulHealthProbe(path, status) {
				return err
			}

			remoteIP := c.RealIP()
			if clientIP, ok := c.Get(ClientIPKey).(string); ok && clientIP != "" {
				remoteIP = clientIP
			}

			attrs := []any{
				"trace_id", traceID(c),
				"method", c.Request().Method,
				"path", path,
				"status", status,
				"latency_ms", time.Since(started).Milliseconds(),
				"remote_ip", remoteIP,
				"bytes_out", bytesOut,
			}
			if err != nil {
				attrs = append(attrs, "error", redactLogValue(err.Error()))
			}

			logger.Info("http request", attrs...)

			return err
		}
	}
}

// isSuccessfulHealthProbe reports whether the access log may drop this request.
// The match is exact (no prefix matching), so user routes such as
// /health-data or /api/v2/health keep their access log.
func isSuccessfulHealthProbe(path string, status int) bool {
	if status < http.StatusOK || status >= http.StatusMultipleChoices {
		return false
	}
	switch path {
	case "/health", "/ready", "/healthz":
		return true
	default:
		return false
	}
}

func recoveryMiddleware(logger *slog.Logger) echo.MiddlewareFunc {
	return func(next echo.HandlerFunc) echo.HandlerFunc {
		return func(c *echo.Context) (err error) {
			defer func() {
				recovered := recover()
				if recovered == nil {
					return
				}

				logger.Error(
					"panic recovered",
					"trace_id", traceID(c),
					"panic", redactLogValue(fmt.Sprint(recovered)),
					"stack", string(debug.Stack()),
				)

				_ = writeAPIError(c, http.StatusInternalServerError, oapimodels.ErrorCodeINTERNALERROR, "Internal server error")
				err = nil
			}()

			return next(c)
		}
	}
}

func errorHandler(logger *slog.Logger) echo.HTTPErrorHandler {
	return func(c *echo.Context, err error) {
		if response, unwrapErr := echo.UnwrapResponse(c.Response()); unwrapErr == nil && response != nil && response.Committed {
			return
		}

		status := http.StatusInternalServerError
		if fromError := echo.StatusCode(err); fromError != 0 {
			status = fromError
		}

		code, message := errorResponseForStatus(status)
		logger.Error(
			"http request failed",
			"trace_id", traceID(c),
			"status", status,
			"error", redactLogValue(err.Error()),
		)

		_ = writeAPIError(c, status, code, message)
	}
}

func errorResponseForStatus(status int) (oapimodels.ErrorCode, string) {
	switch status {
	case http.StatusBadRequest:
		return oapimodels.ErrorCodeVALIDATIONFAILED, "Invalid request"
	case http.StatusUnauthorized:
		return oapimodels.ErrorCodeUNAUTHORIZED, "Unauthorized"
	case http.StatusForbidden:
		return oapimodels.ErrorCodeFORBIDDEN, "Forbidden"
	case http.StatusNotFound:
		return oapimodels.ErrorCode("NOT_FOUND"), "Not found"
	case http.StatusMethodNotAllowed:
		return oapimodels.ErrorCode("METHOD_NOT_ALLOWED"), "Method not allowed"
	case http.StatusRequestEntityTooLarge:
		return oapimodels.ErrorCodePAYLOADTOOLARGE, "Payload too large"
	case http.StatusUnsupportedMediaType:
		return oapimodels.ErrorCodeUNSUPPORTEDMEDIATYPE, "Unsupported media type"
	case http.StatusUnprocessableEntity:
		return oapimodels.ErrorCodeVALIDATIONFAILED, "Validation failed"
	case http.StatusTooManyRequests:
		return oapimodels.ErrorCodeRATELIMITED, "Rate limited"
	case http.StatusBadGateway:
		return oapimodels.ErrorCodeDEPENDENCYERROR, "Dependency error"
	case http.StatusServiceUnavailable:
		return oapimodels.ErrorCodeDEPENDENCYUNAVAILABLE, "Service unavailable"
	default:
		if status >= http.StatusInternalServerError {
			return oapimodels.ErrorCodeINTERNALERROR, "Internal server error"
		}
		return oapimodels.ErrorCodeVALIDATIONFAILED, "Request rejected"
	}
}

func writeAPIError(c *echo.Context, status int, code oapimodels.ErrorCode, message string) error {
	path := c.Request().URL.Path
	if path == "" {
		path = "/"
	}

	traceIDValue := traceID(c)
	traceIDPtr := oapimodels.UUID(traceIDValue)
	timestamp := strfmt.DateTime(time.Now().UTC())

	return c.JSON(status, oapimodels.APIError{
		Code:      &code,
		Message:   &message,
		Path:      &path,
		Timestamp: &timestamp,
		TraceID:   &traceIDPtr,
	})
}

func traceID(c *echo.Context) string {
	if value, ok := c.Get(TraceIDKey).(string); ok && value != "" {
		return value
	}

	// APIError requires traceId. This fallback should only be reachable when a
	// caller bypasses NewRouter, such as a focused middleware unit test.
	fallback := uuid.NewString()
	c.Set(TraceIDKey, fallback)
	return fallback
}

var (
	secretAssignmentPattern = regexp.MustCompile(
		`(?i)(password|passwd|secret|token|api[_-]?key|access[_-]?key|refresh[_-]?token|access[_-]?token|authorization)["']?\s*[=:]\s*["']?[^\s&,;"']+`,
	)
	bearerPattern = regexp.MustCompile(`(?i)bearer\s+[a-z0-9._~+/=-]+`)
)

// redactLogValue prevents common credential shapes from reaching structured
// logs. Request bodies and headers are never logged in the first place.
func redactLogValue(value string) string {
	value = bearerPattern.ReplaceAllString(value, "Bearer [REDACTED]")
	value = secretAssignmentPattern.ReplaceAllString(value, "$1=[REDACTED]")
	return value
}
